import {UNITS,measurement,unitInfo,quantitySummary,setting,leaves,ancestry,descendants,shiftDate,weekStart} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const numberText=n=>new Intl.NumberFormat('ja-JP',{maximumFractionDigits:3}).format(n);
export function quantitySettingsFields(s,id){const m=measurement(s,id);return `<div class="quantity-config"><h3>取り組んだ量</h3><div class="form-columns"><label>記録する単位<select name="quantity-unit" data-quantity-unit>${Object.entries(UNITS).map(([k,u])=>`<option value="${k}" ${m.unit===k?'selected':''}>${u.label}</option>`).join('')}<option value="custom" ${m.unit==='custom'?'selected':''}>自由に入力</option></select></label><label>週の目標量（任意）<input type="number" inputmode="decimal" name="weekly-target" min="0.001" max="1000000" step="any" value="${m.weeklyTarget??''}" placeholder="例：50"></label></div><label data-custom-unit ${m.unit==='custom'?'':'hidden'}>単位の名前<input name="custom-unit" maxlength="12" value="${esc(m.customUnit||'')}" placeholder="例：曲、km、セット"></label><p class="footnote">実績は葉っぱを押して記録します。単位を変更しても過去の記録はそのまま残ります。</p></div>`}
export function recordPanel(s,id,date,today){const n=s.nodes.find(n=>n.id===id);if(!n)return '';const old=s.logs[date]?.[id],m=old?.quantity?.measurement||measurement(s,id),u=unitInfo(m),week=weekStart(date),summary=quantitySummary(s,week,shiftDate(week,6),id,week===weekStart(today)),group=summary.groups.find(g=>g.dimension===u.dimension),amount=old?.quantity?.amount??'',active=setting(s,id);const increments=u.dimension==='time'?(u.label==='分'?[10,30,60]:[.25,.5,1]):[1,5,10];return `<form id="quantity-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(s,id).slice(1,-1).join(' / ')||'自分の木')}</div><h2>${esc(n.name)}</h2></div><button type="button" class="round-button" data-do="close" aria-label="閉じる">×</button></div><label>記録する日<input type="date" name="record-date" value="${date}" max="${today}" required></label><label class="quantity-input-label">この日の合計<div class="quantity-input"><input name="amount" type="number" inputmode="decimal" min="0.001" max="1000000" step="any" value="${amount}" placeholder="0" required autofocus><span>${esc(u.label)}</span></div></label><div class="quantity-increments">${increments.map(v=>`<button type="button" data-add-quantity="${v}">＋${numberText(v)}${esc(u.label)}</button>`).join('')}</div><div class="record-week-summary"><span>この週の合計</span><strong>${numberText(group?.total||0)}<small>${esc(group?.unit||(u.dimension==='time'?'時間':u.label))}</small></strong></div>${old&&!old.quantity?'<p class="footnote">この日には以前のチェック記録があります。量はまだ記録されていません。</p>':''}${old?.quantity?'<p class="footnote">保存すると、この日の合計を更新します。過去の記録の単位を使用しています。</p>':'<p class="footnote">1日に何回か取り組んだ場合は、合計量を入力してください。</p>'}${active.type==='once'?'<p class="footnote">記録すると、この行動は完了になります。</p>':''}<div class="dialog-actions"><button type="button" class="text-button" data-edit="${esc(id)}" data-quantity-settings>単位・目標の設定</button><button type="submit" class="primary">量を記録する</button></div>${old?`<button type="button" class="text-button danger remove-quantity" data-remove-quantity="${esc(id)}" data-log-date="${date}">この日の記録を削除</button>`:''}</form>`}
export function weeklyPanel(s,{week,scope,dimension,today}){const end=shiftDate(week,6),current=weekStart(today),summary=quantitySummary(s,week,end,scope,week===current),group=summary.groups.find(g=>g.dimension===dimension)||summary.groups[0],goal=s.nodes.find(n=>n.id===scope),label=goal?.name||'木全体';const dates=Array.from({length:7},(_,i)=>shiftDate(week,i)),max=Math.max(1,...dates.map(d=>group?.byDate[d]||0));return `<section class="quantity-overview" aria-label="取り組んだ量"><header class="quantity-week-heading"><div><span class="eyebrow">${esc(label)}</span><h1>${week===current?'今週の積み重ね':'この週の積み重ね'}</h1></div><div class="week-navigation"><button class="round-button" data-quantity-week="-1" aria-label="前の週">←</button><span>${week.slice(5).replace('-','/')} — ${end.slice(5).replace('-','/')}</span><button class="round-button" data-quantity-week="1" aria-label="次の週" ${week>=current?'disabled':''}>→</button></div></header><div class="quantity-totals">${summary.groups.map(g=>`<button class="quantity-total ${group===g?'chosen':''}" data-quantity-dimension="${esc(g.dimension)}" aria-pressed="${group===g}"><strong>${numberText(g.total)}</strong><span>${esc(g.unit)}</span></button>`).join('')||'<div class="quantity-empty"><span>♧</span><h2>取り組んだ量を、少しずつ。</h2><p>葉っぱで単位を設定し、ページ数や時間を記録しましょう。</p><button class="primary" data-view="tree">木から記録する</button></div>'}</div>${group?`<div class="quantity-chart" aria-label="${esc(group.unit)}の1週間の記録">${dates.map((d,i)=>{const v=group.byDate[d]||0;return `<button class="quantity-day ${d===today?'today':''}" data-quantity-day="${d}" aria-label="${d.slice(5).replace('-','月')}日 ${numberText(v)}${esc(group.unit)}" ${d>today?'disabled':''}><span class="bar-value">${v?numberText(v):''}</span><div class="bar-track"><i style="height:${v?Math.max(3,v/max*100):2}%;opacity:${v?1:.25}"></i></div><span>${['月','火','水','木','金','土','日'][i]}</span></button>`}).join('')}</div><div class="quantity-section-title"><h2>行動ごとの量</h2><button class="text-button" data-reset-week ${week===current?'hidden':''}>今週へ戻る</button></div><div class="quantity-action-list">${summary.rows.map(row=>{const pct=row.target?Math.round(row.amount/row.target*100):null;return `<div class="quantity-action"><div class="quantity-action-top"><div><strong>${esc(row.name)}</strong>${row.deleted?'<small>削除済みの行動の記録</small>':''}</div><div><b>${numberText(row.amount)}</b><span>${row.target?` / ${numberText(row.target)}`:''} ${esc(row.unit)}</span>${!row.deleted&&leaves(s).some(n=>n.id===row.id)?`<button class="round-button" data-record-leaf="${esc(row.id)}" aria-label="${esc(row.name)}の量を記録">＋</button>`:''}</div></div>${pct!=null?`<div class="quantity-target-bar"><i style="width:${Math.min(100,pct)}%"></i></div><p class="quantity-target-caption">週の目標 ${pct}%</p>`:''}</div>`}).join('')}</div>`:''}${summary.unknown?`<p class="footnote legacy-quantity">量が未記録のチェック ${summary.unknown}件は、量の合計に含めていません。</p>`:''}</section>`}
export function scopeOptions(s,selected){const root=s.nodes.find(n=>n.parentId===null),out=[];function walk(n,depth){out.push(`<option value="${esc(n.id)}" ${selected===n.id?'selected':''}>${'　'.repeat(depth)}${esc(n.name)}</option>`);s.nodes.filter(c=>c.parentId===n.id).forEach(c=>walk(c,depth+1))}if(root)walk(root,0);return `<option value="all" ${selected==='all'?'selected':''}>木全体</option>`+out.join('')}
